// Symptom: the landing band and the ops map controls change stack level (z-index).
// The band must keep its stack level on the landing screen, and the map controls must keep theirs on the radar screen.
await page.goto('/login');
const band = page.getByRole('region', { name: 'Landing band' });
await expect(band).toBeVisible();
const bandZ = await band.evaluate((el) => getComputedStyle(el).zIndex);
await page.getByRole('button', { name: 'Sign in' }).hover();
await expect(band).toHaveCSS('z-index', bandZ);

await page.goto('/ops/radar');
const zoomIn = page.getByRole('button', { name: 'Zoom in' });
await expect(zoomIn).toBeVisible();
const zoomZ = await zoomIn.evaluate((el) => getComputedStyle(el).zIndex);
await page.getByRole('button', { name: 'Zoom out' }).hover();
await expect(zoomIn).toHaveCSS('z-index', zoomZ);
```

